let chartOffset=0, chartTotal=0;
let engine=new Engine(crypto.getRandomValues(new Uint32Array(1))[0]),side='buy',view='price',tab='positions',running=false,saveError=false;
try{const data=localStorage.getItem('yenfx-v1');if(data)engine=Engine.restore(JSON.parse(data));}catch{saveError=true;}
function feedback(message,error=false){$('feedback').textContent=message;$('feedback').className=error?'negative':'positive';}
function save(){try{localStorage.setItem('yenfx-v1',JSON.stringify({version:2,engine:engine.snapshot()}));$('saveStatus').textContent='已自动保存 · 本浏览器';}catch{$('saveStatus').textContent='无法保存，请导出记录';}}
function color(el,value){el.classList.toggle('positive',value>0);el.classList.toggle('negative',value<0);}
function render(){renderGame();renderBrief(engine);const a=engine.account(),r=engine.rules();$('boldMode').checked=!engine.isRealtime()&&engine.bold;$('boldMode').disabled=engine.isRealtime()||!!engine.settlement||engine.halted||!!engine.positions.length||!!engine.orders.length;$('modeInfo').textContent='第 '+engine.round+' 局 · '+(engine.bold?'挑战：2.5%保证金 / 75%强平线 / 最大40×':'标准：4%保证金 / 100%强平线 / 最大25×')+' · 每第三局含一次随机极端行情'+(engine.positions.some(p=>p.marginRate!==r.marginRate)?' · 旧仓保留开仓保证金率':'');$('modeChip').textContent=engine.isRealtime()?'免保证金':engine.bold?'最大40×':'最大25×';if(engine.isRealtime())$('modeInfo').textContent='第 '+engine.round+' 局 · 现实20分钟 / 全天交易 / 无保证金占用及保证金强平';$('freeLabel').textContent=engine.isRealtime()?'可用净资金':'可用保证金';$('ratioLabel').textContent=engine.isRealtime()?'保证金规则':'保证金维持率';$('estimateLabel').textContent=engine.isRealtime()?'本模式保证金占用':'预计新增保证金';$('riskMath').textContent=engine.isRealtime()?'不按维持率强平 · 净资金耗尽结束':'净值 ÷ 必要保证金';$('marginHint').textContent='按中间价 × 数量 × '+r.marginRate*100+'%';$('liquidationLabel').textContent=engine.isRealtime()?'免保证金 · 净资金耗尽结束':'强平线 '+r.liquidationRatio*100+'%';$('units').max=r.maxUnits;for(const id of ['allBuy','allSell'])$(id).disabled=(!engine.bold&&!engine.isRealtime())||engine.halted||!!engine.settlement||!engine.isOpen();$('equity').textContent=yen(a.equity);$('balance').textContent=yen(a.balance);$('floating').textContent=(a.floating>=0?'+':'−')+yen(Math.abs(a.floating));color($('floating'),a.floating);$('free').textContent=yen(a.free);$('margin').textContent='占用 '+yen(a.margin);$('ratio').textContent=Number.isFinite(a.ratio)?(a.ratio*100).toFixed(1)+'%':'—';color($('ratio'),Number.isFinite(a.ratio)?a.ratio-r.liquidationRatio*1.5:0);$('leverage').textContent='实际杠杆 '+a.leverage.toFixed(2)+'×';$('return').textContent='初始本金以来 '+(((a.equity-engine.debt())/RULES.initial-1)*100).toFixed(2)+'%';color($('return'),a.equity-engine.debt()-RULES.initial);$('bid').textContent=engine.bid.toFixed(3);$('ask').textContent=engine.ask.toFixed(3);$('spread').textContent=(engine.spread/.01).toFixed(2)+' pips';$('clock').textContent=clock(engine.time)+' JST';$('marketStatus').textContent=engine.halted?'本局结束 · 虚拟负债 '+yen(Math.max(0,-a.equity)):engine.isRealtime()?'● 全天连续交易':engine.isOpen()?'● 市场开放':'○ 周末休市';$('seedLabel').textContent=engine.seed;$('drawdown').textContent=(engine.maxDrawdown*100).toFixed(2)+'%';$('positionCount').textContent=engine.positions.length;$('orderCount').textContent=engine.orders.length;$('riskBar').style.width=(Number.isFinite(a.ratio)?Math.min(100,Math.max(0,(a.ratio/r.liquidationRatio-1)*50)):100)+'%';$('submit').disabled=engine.halted||!engine.isOpen();estimate();renderLedger();draw();renderSettlement();renderLoans(engine,$,yen,clock);$('microState').textContent='点差 '+(engine.spread/.01).toFixed(2)+' pips · 深度 '+Math.round(engine.depth/1000)+'K '+INSTRUMENTS[engine.pair].base+' · '+(engine.market.state==='stress'?'波动活跃':engine.market.state==='trend'?'趋势阶段':'区间阶段');$('skipClosed').disabled=engine.isOpen()||!!engine.settlement||engine.halted;$('paceStatus').textContent=engine.isRealtime()?'现实倒计时独立于行情 · 固定1秒=1模拟分钟 · 暂停/离开页面不延长截止时间':engine.positions.length&&engine.account().ratio<engine.rules().liquidationRatio*1.25?'接近强平 · 播放自动降至1×，可暂停管理仓位':engine.tick<10?'入门阶段保持1× · 指导结束后按所选速度推进':'当前 '+$('speed').value+'× · 推进时间同步计息、挂单及风险检查';}
function draft(){return {pair:engine.pair,side,type:$('type').value,units:value('units'),price:value('price'),sl:value('sl'),tp:value('tp'),trail:value('trail')==null?null:value('trail')*.01};}
function estimate(){const u=Number($('units').value);$('estimate').textContent=Number.isFinite(u)?yen(u*engine.mid*engine.rules().marginRate):'—';renderCoach();renderNews();}
function renderCoach(){const realElapsed=engine.game.startedAt==null?0:Math.max(0,Date.now()-engine.game.startedAt),window=engine.isRealtime()?{active:realElapsed<180000,remaining:Math.ceil((180000-realElapsed)/1000)}:guidanceWindow(engine.tick);$('coachPanel').hidden=!window.active||!!engine.settlement;$('guideCountdown').textContent=engine.isRealtime()?`指导剩余 ${window.remaining} 现实秒`:`剩余 ${window.remaining} 个模拟分钟`;const c=coaching(engine,draft());$('coachTitle').textContent=c.title;$('coachText').textContent=c.text;$('coachObservation').textContent=c.observation;$('coachPanel').dataset.tone=c.tone;$('coachSteps').replaceChildren();c.steps.forEach((step,i)=>{const node=document.createElement('span');node.textContent=(i<c.stage?'✓ ':`${i+1} `)+step;node.className=i===c.stage?'current':i<c.stage?'done':'';$('coachSteps').append(node);});$('plannedRisk').textContent=$('type').value==='oco'?'OCO两侧需要分别规划风险；共用移动止损可在成交后生效。':c.planned==null?'先设置方向正确的止损价以估算计划风险':`计划止损 ${yen(c.planned)} · 占净值 ${(c.planned/engine.account().equity*100).toFixed(2)}%（不含跳空与额外滑点）`;}
function renderNews(){renderTicker();const feed=$('newsFeed');feed.replaceChildren();const news=allNews();$('newsCount').textContent=news.length?`${news.length} 条已发布`:'等待市场报道';if(!news.length){const p=document.createElement('p');p.className='news-empty';p.textContent='暂无报道。市场不会提前告诉你下一次冲击的时间、方向或幅度。';feed.append(p);return;}for(const n of news.slice(0,6)){const card=document.createElement('article');const meta=document.createElement('small');meta.textContent=`${clock(n.publishedAt)} JST · ${n.tag} · 虚构`;const title=document.createElement('h3');title.textContent=n.title;const body=document.createElement('p');body.textContent=n.body;card.append(meta,title,body);feed.append(card);}}
function allNews(){return Object.keys(INSTRUMENTS).flatMap(pair=>engine.instrument(pair).market.news.map(n=>({...n,id:pair+'-'+n.id,title:INSTRUMENTS[pair].label+' · '+n.title}))).sort((a,b)=>b.publishedAt-a.publishedAt||String(b.id).localeCompare(String(a.id))).slice(0,60);}
let lastTickerKey=null;
function renderTicker(){const news=allNews(),key=tickerKey(news);if(key===lastTickerKey)return;lastTickerKey=key;const track=$('tickerTrack');track.replaceChildren();const items=tickerItems(news),group=document.createElement('div');group.className='ticker-group';if(!items.length){const empty=document.createElement('div');empty.className='ticker-placeholder';empty.textContent='USD/JPY · 模拟市场  /  等待新闻发布  /  资讯为游戏生成的虚构新闻';group.append(empty);}else for(const n of items){const a=document.createElement('a');a.className='ticker-item';a.href='#newsFeed';const time=document.createElement('time');time.textContent=clock(n.time)+' JST';const tag=document.createElement('b');tag.textContent=n.tag;const title=document.createElement('span');title.textContent=n.title;a.append(time,tag,title);group.append(a);}const duplicate=group.cloneNode(true);duplicate.setAttribute('aria-hidden','true');duplicate.querySelectorAll('a').forEach(a=>a.tabIndex=-1);track.append(group,duplicate);track.style.setProperty('--ticker-duration',tickerDuration(items)+'s');}
$('toggleTicker').onclick=()=>{const paused=$('newsTicker').classList.toggle('paused');$('toggleTicker').textContent=paused?'继续滚动':'暂停滚动';$('toggleTicker').setAttribute('aria-pressed',String(paused));};
function setSide(value){side=value;$('buy').classList.toggle('selected',side==='buy');$('sell').classList.toggle('selected',side==='sell');document.querySelector('.side-toggle').classList.toggle('sell',side==='sell');$('submit').classList.toggle('sell',side==='sell');$('submit').textContent=$('type').value==='oco'?'提交双向突破 OCO':(side==='buy'?'买入':'卖出')+' '+INSTRUMENTS[engine.pair].label;renderCoach();}
const value=id=>$(id).value.trim()===''?null:Number($(id).value);
$('buy').onclick=()=>setSide('buy');$('sell').onclick=()=>setSide('sell');$('units').oninput=estimate;
document.querySelectorAll('[data-units]').forEach(b=>b.onclick=()=>{$('units').value=b.dataset.units;estimate();});
$('type').onchange=()=>{const type=$('type').value,oco=type==='oco';$('priceLabel').firstChild.textContent=oco?'上方买入触发价':'挂单价格';$('priceLabel').hidden=type==='market';$('price').required=type!=='market';$('lowerLabel').hidden=!oco;$('lower').required=oco;$('expiryLabel').hidden=type==='market';$('sl').disabled=oco;$('tp').disabled=oco;$('buy').disabled=oco;$('sell').disabled=oco;if(oco){$('price').value=(engine.ask+.15).toFixed(3);$('lower').value=(engine.bid-.15).toFixed(3);}else if(!$('price').value)$('price').value=engine.mid.toFixed(3);setSide(side);};
$('orderForm').onsubmit=e=>{e.preventDefault();try{const o=draft(),expiry=Number($('expiry').value);o.expiry=expiry?engine.time+expiry*60000:null;if(o.type==='oco')engine.placeOCO({units:o.units,upper:o.price,lower:value('lower'),trail:o.trail,expiry:o.expiry});else engine.place(o);feedback(o.type==='market'?'订单已成交，见右侧持仓。':'挂单已提交，触发时检查资金。');save();render();}catch(e){feedback(e.message,true);}};
for(const id of ['price','lower','sl','tp','trail','riskPercent'])$(id).addEventListener('input',renderCoach);
$('toggleCoach').onclick=()=>{$('coachBody').hidden=!$('coachBody').hidden;$('toggleCoach').textContent=$('coachBody').hidden?'展开指导':'收起指导';};
$('sizeRisk').onclick=()=>{try{if($('type').value==='oco')throw Error('OCO两侧风险不同，请分别规划数量');const o=draft(),c=coaching(engine,o),a=engine.account(),pct=value('riskPercent');if(!c.validSL)throw Error('先填写方向正确的止损价格');if(!Number.isFinite(pct)||pct<.1||pct>10)throw Error('计划风险比例须为 0.1%–10%');const entry=o.type==='market'?(side==='buy'?engine.ask:engine.bid):o.price;const gap=Math.abs(entry-o.sl),slip=engine.spread*.5+engine.vol*.05;const byRisk=Math.floor(a.equity*pct/100/(gap+slip)/1000)*1000;const byMargin=Math.floor(Math.max(0,a.free)/(engine.mid*engine.rules().marginRate+engine.spread+.02)/1000)*1000;const cap=Math.floor(Math.max(0,engine.rules().maxExposure-a.exposure)/engine.mid/1000)*1000;const units=Math.min(byRisk,byMargin,cap,engine.rules().maxUnits);if(units<1000)throw Error('所选风险预算或可用保证金不足以交易最小单位');$('units').value=units;estimate();feedback('数量已填写；额外滑点和跳空仍可能突破预算。');}catch(e){feedback(e.message,true);}};
function act(fn){try{fn();feedback('操作完成');save();render();}catch(e){feedback(e.message,true);}}
$('step').onclick=()=>jump(1);
$('boldMode').onchange=()=>act(()=>engine.setBold($('boldMode').checked));$('allBuy').onclick=()=>act(()=>engine.allIn('buy'));$('allSell').onclick=()=>act(()=>engine.allIn('sell'));
function playback(){if(engine.settlement)return;paceCarry=0;lastFrame=performance.now();if(engine.isRealtime()){engine.beginRealtime();running=true;save();render();return;}running=!running;$('play').textContent=running?'Ⅱ 暂停行情':'▶ 开始行情';}
$('play').onclick=playback;let saveTicks=0;
let paceCarry=0;
let lastFrame=performance.now(),lastRenderSecond=-1;
setInterval(()=>{const now=Date.now(),frame=performance.now(),elapsed=Math.max(0,Math.min(5000,frame-lastFrame));lastFrame=frame;const expired=engine.updateRealtime(now);if(engine.isRealtime()&&engine.game.startedAt!=null&&!engine.settlement&&!engine.halted)running=true;let n=0;if(running&&!engine.settlement&&!engine.halted){const speed=engine.isRealtime()?1:effectiveSpeed(liquidationSpeed(Number($('speed').value),engine.account().ratio,engine.rules().liquidationRatio,!!engine.positions.length),engine.tick);paceCarry+=elapsed/1000*speed;n=Math.floor(paceCarry);if(n){paceCarry-=n;advanceMinutes(engine,n);}}
if(engine.halted||engine.settlement){running=false;$('play').textContent='▶ 开始行情';}if(expired||n&&++saveTicks%5===0)save();const second=Math.floor(now/1000);if(n||expired||engine.isRealtime()&&second!==lastRenderSecond){lastRenderSecond=second;render();}},250);
document.addEventListener('visibilitychange',()=>{if(engine.updateRealtime())save();lastFrame=performance.now();render();});
$('speed').onchange=()=>{paceCarry=0;render();};
function jump(minutes){if(engine.isRealtime())return feedback('20分钟模式按固定现实节奏连续推进，不支持快进。',true);advanceMinutes(engine,minutes);if(engine.halted||engine.settlement){running=false;$('play').textContent='▶ 开始行情';}save();render();}
$('skipClosed').onclick=()=>{try{running=false;const minutes=engine.skipClosed();feedback('已跳过 '+minutes+' 个休市模拟分钟；借款与到期订单已检查。');save();render();}catch(e){feedback(e.message,true);}};$('jump5').onclick=()=>jump(5);$('jump15').onclick=()=>jump(15);
window.addEventListener('pagehide',save);
$('closeAll').onclick=()=>{if(!engine.positions.length)return feedback('当前没有持仓');act(()=>{for(const p of [...engine.positions])if(engine.positions.some(x=>x.id===p.id))engine.close(p.id);});};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));draw();});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===b));renderLedger();});
function renderLedger(){const box=$('ledgerContent'),scroll=box.scrollTop,opened=new Set([...box.querySelectorAll('details[open]')].map(x=>x.dataset.position));box.replaceChildren();if(tab==='logs'){for(const l of engine.logs.slice(0,100)){const row=document.createElement('div');row.className='log-row';const t=document.createElement('time');t.textContent=clock(l.time);const type=document.createElement('b');type.textContent=l.type;const msg=document.createElement('span');msg.textContent=l.message;if(l.pnl!=null)msg.className=l.pnl>=0?'positive':'negative';row.append(t,type,msg);box.append(row);}return;}
const items=tab==='positions'?engine.positions:engine.orders;if(!items.length){box.innerHTML='<div class="empty"><b>'+(tab==='positions'?(engine.logs.some(l=>l.type==='建仓')?'当前没有持仓。':'你的第一笔交易，从这里开始。'):'尚无等待成交的订单。')+'</b>'+(tab==='positions'?'在右侧选择方向与数量，建立你的持仓。':'提交限价单或突破单，等待报价触发。')+'</div>';return;}
for(const p of items){const card=document.createElement('article');card.className='position-card';const heading=document.createElement('div');heading.className='position-heading';const direction=document.createElement('b');direction.textContent=(p.side==='buy'?'多头':'空头')+' · '+num(p.units)+' '+INSTRUMENTS[p.pair??'USDJPY'].base+' · '+(p.pair??'USDJPY');direction.className=p.side==='buy'?'positive':'negative';const id=document.createElement('small');id.textContent='#'+p.id;heading.append(direction,id);card.append(heading);const mark=document.createElement('div');mark.className='position-value';const quote=document.createElement('span');quote.textContent=tab==='positions'?'建仓 '+p.entry.toFixed(5):'触发 '+p.price.toFixed(3);const result=document.createElement('strong');result.textContent=tab==='positions'?yen(engine.pnl(p)):(p.type==='limit'?'限价':'突破')+(p.group?' · OCO':'');if(tab==='positions')result.className=engine.pnl(p)>=0?'positive':'negative';mark.append(quote,result);card.append(mark);const protection=document.createElement('small');protection.className='position-protection';protection.textContent='止损 '+(p.sl?.toFixed(3)??'—')+' / 止盈 '+(p.tp?.toFixed(3)??'—')+(p.trail!=null?' · 跟踪 '+(p.trail/.01).toFixed(0)+'p':'')+(p.expiry?' · 到期 '+clock(p.expiry):'');card.append(protection);if(tab==='positions'){const mini=document.createElement('canvas');mini.className='position-chart';mini.setAttribute('aria-label','持仓 #'+p.id+' 浮动盈亏折线图');card.append(mini);const note=document.createElement('small');note.className='position-protection';note.textContent='自建仓起 · 按当前剩余数量回算 · 不含已实现盈亏/掉期';card.append(note);requestAnimationFrame(()=>{if(mini.isConnected)drawPosition(mini,engine.instrument(p.pair??'USDJPY').history,p);});}const actions=document.createElement('div');actions.className='position-actions';const button=(label,fn,target=actions)=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>act(fn);target.append(b);return b;};if(tab==='positions'){button('平仓',()=>engine.close(p.id)).className='close-position';const half=button('减半',()=>engine.close(p.id,Math.floor(p.units/2000)*1000));half.disabled=p.units<2000;const tools=document.createElement('details');tools.className='position-tools';tools.dataset.position=String(p.id);tools.open=opened.has(String(p.id));const summary=document.createElement('summary');summary.textContent='保护设置';tools.append(summary);const controls=document.createElement('div');button('止损/止盈',()=>{const sl=prompt('止损价格，留空清除',p.sl??'');if(sl===null)return;const tp=prompt('止盈价格，留空清除',p.tp??'');if(tp===null)return;engine.modify(p.id,sl.trim()?Number(sl):null,tp.trim()?Number(tp):null);},controls);button('移动止损',()=>{const text=prompt('移动止损距离 / pips（1–1,000），留空关闭并保留当前止损价',p.trail==null?'20':String(p.trail/.01));if(text!==null)engine.setTrail(p.id,text.trim()?Number(text)*.01:null);},controls);button('保本止损',()=>engine.modify(p.id,p.entry,p.tp),controls);tools.append(controls);actions.append(tools);}else{if(!p.group)button('修改',()=>{const price=prompt('新的触发价格',String(p.price));if(price===null)return;const units=prompt('新的数量 '+INSTRUMENTS[p.pair??'USDJPY'].base,String(p.units));if(units!==null)engine.editOrder(p.id,{price:Number(price),units:Number(units)});});button('撤单',()=>engine.cancel(p.id));}card.append(actions);box.append(card);}box.scrollTop=scroll;}
function draw(){const period=Number($('candlePeriod').value);const nextTotal=Math.max(0,candlesFromQuotes(engine.history,period).length-80);if(chartOffset>0)chartOffset=Math.max(0,chartOffset+nextTotal-chartTotal);const result=drawChart($('chart'),engine,view,period,chartOffset);$('chartCaption').textContent=result.caption;$('ohlc').textContent=result.ohlc;$('candlePeriod').disabled=view!=='price';chartOffset=result.offset??0;chartTotal=result.maxOffset??0;$('historyScroll').max=chartTotal;$('historyScroll').value=chartTotal-chartOffset;$('historyTools').hidden=view!=='price';$('latestChart').disabled=chartOffset===0;}
$('candlePeriod').onchange=()=>{chartOffset=0;chartTotal=0;draw();};
$('historyScroll').oninput=()=>{chartOffset=chartTotal-Number($('historyScroll').value);draw();};$('latestChart').onclick=()=>{chartOffset=0;draw();};
function scrollChart(n){if(view!=='price')return;chartOffset=Math.max(0,Math.min(chartTotal,chartOffset+n));draw();}
$('olderChart').onclick=()=>scrollChart(40);$('newerChart').onclick=()=>scrollChart(-40);
$('chart').addEventListener('wheel',e=>{if(view!=='price'||!chartTotal)return;e.preventDefault();scrollChart((e.deltaX||e.deltaY)>0?8:-8);},{passive:false});
let dragX=null,dragOffset=0;$('chart').onpointerdown=e=>{dragX=e.clientX;dragOffset=chartOffset;$('chart').setPointerCapture(e.pointerId);};$('chart').onpointermove=e=>{if(dragX==null||view!=='price')return;chartOffset=Math.max(0,Math.min(chartTotal,dragOffset+Math.round((e.clientX-dragX)/7)));draw();};$('chart').onpointerup=$('chart').onpointercancel=()=>{dragX=null;};

new ResizeObserver(draw).observe($('chart'));
$('help').onclick=()=>$('rules').showModal();$('dismiss').onclick=()=>$('rules').close();
function restart(){chartOffset=0;lastEnded=false;$('loanForm').reset();$('repayAmount').value='';$('loanFeedback').textContent='';lastTickerKey=null;$('newsTicker').classList.remove('paused');$('toggleTicker').textContent='暂停滚动';$('toggleTicker').setAttribute('aria-pressed','false');running=false;saveTicks=0;lastFrame=performance.now();engine=new Engine(crypto.getRandomValues(new Uint32Array(1))[0],engine.round+1);engine.bold=true;engine.setGameMode($('gameMode').value||'free');$('orderForm').reset();$('speed').value='3';paceCarry=0;$('candlePeriod').value='5';$('coachBody').hidden=false;$('toggleCoach').textContent='收起指导';side='buy';view='price';tab='positions';$('play').textContent='▶ 开始行情';$('type').onchange();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));feedback('新账户已创建 · 初始资金 ¥1,000,000');save();render();window.scrollTo({top:0,behavior:'smooth'});}
$('reset').onclick=()=>{if(!confirm('重置本局资金、持仓和记录？需要保留的记录请先结算并导出PNG。'))return;restart();};
$('restartGame').onclick=restart;
$('settleRound').onclick=()=>{try{running=false;$('play').textContent='▶ 开始行情';engine.settle();save();render();$('settlementPanel').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){feedback(e.message,true);}};
let lastEnded=false;
function renderSettlement(){const r=engine.settlement,ended=!!r;$('settlementPanel').hidden=!ended;if(ended&&!lastEnded)setTimeout(()=>{(r.loanDefault?$('loanFailure'):$('settlementPanel')).scrollIntoView({behavior:'smooth',block:'start'});},0);lastEnded=ended;for(const id of ['play','step','jump5','jump15','speed','settleRound','closeAll','reset'])$(id).disabled=ended||engine.isRealtime()&&(['step','jump5','jump15','speed'].includes(id)||id==='play'&&engine.game.startedAt!=null);if(engine.isRealtime())$('play').textContent=ended?'本轮已结束':engine.game.startedAt==null?'▶ 开始现实20分钟':'现实20分钟计时中';for(const element of $('orderForm').elements)element.disabled=ended||(['sl','tp'].includes(element.id)&&$('type').value==='oco');$('buy').disabled=ended||$('type').value==='oco';$('sell').disabled=ended||$('type').value==='oco';$('submit').disabled=ended||engine.halted||!engine.isOpen();if(!ended)return;$('marketStatus').textContent=r.loanDefault?'借款违约 · 游戏结束':'本轮已结算';$('settlementSummary').textContent='最终资金 '+yen(r.final)+' · 净收益 '+(r.net>=0?'+':'−')+yen(Math.abs(r.net))+' · '+r.returnPct.toFixed(2)+'%';color($('settlementSummary'),r.net);const fields=[['初始资金',yen(r.initial)],['最终资金',yen(r.final)],['净收益',yen(r.net)],['收益率',r.returnPct.toFixed(2)+'%'],['建仓次数',r.entries],['平仓成交次数',r.exits],['胜 / 负 / 持平',r.wins+' / '+r.losses+' / '+r.flat],['胜率（含减仓）',r.winRate==null?'—':r.winRate.toFixed(1)+'%'],['盈利成交合计',yen(r.grossProfit)],['亏损成交合计',yen(r.grossLoss)],['隔夜结算合计',yen(r.swap)],['最大回撤',r.maxDrawdown.toFixed(2)+'%'],['模拟 / 现实用时',r.minutes+' 分 / '+(r.realMinutes??0).toFixed(1)+' 分'],['强平次数',r.forced],['累计借入',yen(r.loanBorrowed??0)],['借款利息',yen(r.loanInterest??0)],['未清偿借款',yen(r.unpaidDebt??0)],['借款结果',r.loanDefault?'到期违约 · 本局结束':'已清偿']];$('settlementData').replaceChildren();for(const [label,v]of fields){const cell=document.createElement('div'),title=document.createElement('small'),value=document.createElement('strong');title.textContent=label;value.textContent=v;cell.append(title,value);$('settlementData').append(cell);}const g=r.game;if(g){$('settlementSummary').textContent+=' · 交易评分 '+g.score+'/100（'+g.grade+'） · '+g.mission+(g.complete?' ✓ 达成':' · 未达成');}$('settlementNote').textContent=(r.weekend?'休市：剩余持仓按最后可用 Bid/Ask 报价估值结算，未模拟休市成交。':'已撤销全部挂单，剩余持仓按当前报价及模拟滑点平仓。')+(r.estimated?'旧存档历史日志达到上限，交易次数和胜率可能不完整。':'')+' 胜率以每次平仓成交（含部分减仓）计数；重新开始将清空本轮记录，可先导出PNG。';}
$('export').onclick=()=>{try{exportReport(engine);feedback('PNG总结已导出');}catch(e){feedback(e.message,true);}};
$('loanForm').onsubmit=event=>{event.preventDefault();try{engine.borrow(Number($('loanAmount').value),$('loanPlan').value);$('loanFeedback').textContent='借款已到账，按模拟时间计息，到期自动扣款。';save();render();}catch(e){$('loanFeedback').textContent=e.message;}};
for(const id of ['loanAmount','loanPlan'])$(id).addEventListener('input',()=>renderLoans(engine,$,yen,clock));
function repayLoan(all){try{engine.repay(all?undefined:Number($('repayAmount').value));$('loanFeedback').textContent='还款完成，余额和欠款已更新。';save();render();}catch(e){$('loanFeedback').textContent=e.message;}}
$('repayPart').onclick=()=>repayLoan(false);$('repayAll').onclick=()=>repayLoan(true);
$('exportSettlement').onclick=()=>$('export').click();
const watchButtons=new Map();
function renderGame(){const g=gameResult(engine),m=MISSIONS[engine.game.mission],c=INSTRUMENTS[engine.pair];$('instrumentSelect').value=engine.pair;$('instrumentName').textContent=c.name+' · OTC 模拟';document.querySelector('.flags').textContent={USDJPY:'🇺🇸 🇯🇵',EURJPY:'🇪🇺 🇯🇵',GBPJPY:'🇬🇧 🇯🇵',AUDJPY:'🇦🇺 🇯🇵'}[engine.pair];document.querySelector('.all-in').hidden=!engine.bold&&!engine.isRealtime();$('allBuy').textContent=engine.isRealtime()?'10×参考仓位做多 ↗':'梭哈做多 ↗';$('allSell').textContent=engine.isRealtime()?'10×参考仓位做空 ↘':'梭哈做空 ↘';document.querySelector('.all-in small').textContent=engine.isRealtime()?'一键填入约10×净值的名义仓位；可手动调整数量，无保证金门槛':'使用约85%可用资金 · 预留缓冲与成交成本';$('submit').textContent=$('type').value==='oco'?'提交双向突破 OCO':(side==='buy'?'买入 ':'卖出 ')+c.label;$('chart').setAttribute('aria-label',c.label+' K线图或账户净值曲线');$('quantityLabel').textContent='数量 / '+c.base;$('gameMode').value=engine.game.mode;$('gameMode').disabled=engine.tick>0||engine.stats.entries>0||engine.orders.length>0||engine.game.startedAt!=null||!!engine.settlement;$('missionName').textContent=m.name;$('missionDetail').textContent=m.description+' · 至少交易一次 · 无强平';$('roundProgress').max=engine.isRealtime()?1200:1;$('roundProgress').value=engine.isRealtime()?1200-g.remainingSeconds:0;const mins=Math.floor(g.remainingSeconds/60),secs=String(g.remainingSeconds%60).padStart(2,'0');$('roundClock').textContent=engine.isRealtime()?(engine.game.startedAt==null?'待开始 · 现实20:00':`现实剩余 ${mins}:${secs} · 到时自动结算`):'自由局 · 可随时结算';$('liveScore').textContent=g.score+' / 100';$('missionProgress').textContent=g.complete?'当前已满足任务，结算时确认':'净收益 '+g.net.toFixed(2)+'% · 回撤 '+(engine.maxDrawdown*100).toFixed(1)+'%';for(const [pair,c]of Object.entries(INSTRUMENTS)){const q=engine.instrument(pair);if(!watchButtons.has(pair)){const button=document.createElement('button');button.type='button';button.onclick=()=>switchInstrument(pair);watchButtons.set(pair,button);$('watchlist').append(button);}const b=watchButtons.get(pair);b.className=pair===engine.pair?'selected':'';const change=(q.mid/c.start-1)*100;b.textContent=c.label+'  '+q.mid.toFixed(3)+'  '+(change>=0?'+':'')+change.toFixed(2)+'%';}}
function switchInstrument(pair){engine.setInstrument(pair);chartOffset=chartTotal=0;$('price').value='';$('sl').value='';$('tp').value='';$('type').onchange();save();render();}
$('instrumentSelect').onchange=()=>switchInstrument($('instrumentSelect').value);
$('gameMode').onchange=()=>act(()=>{running=false;paceCarry=0;lastFrame=performance.now();engine.setGameMode($('gameMode').value);});
$('riskPreset').onclick=()=>{if($('type').value!=='market')return feedback('风险模板用于市价单；挂单请自行设置保护价格。',true);const entry=side==='buy'?engine.ask:engine.bid,gap=Math.max(.08,Math.min(.35,engine.vol*Math.sqrt(15)*2.5));$('sl').value=(entry+(side==='buy'?-gap:gap)).toFixed(3);$('tp').value=(entry+(side==='buy'?gap*1.8:-gap*1.8)).toFixed(3);$('riskPercent').value=1;$('sizeRisk').click();};
if(engine.updateRealtime())save();render();if(saveError)feedback('未能读取本地存档，已创建新账户；建议导出记录。',true);


